BLOOD_INTRO = '## 3. Synthetic-blood stage: fixed preprocessing, models and controls\nThe following sections preserve the validated blood workflow and formal model selection. The historical transfer comparator remains archived; the new Handiprint GPU heads are not substituted. Both stages use related pairs, so interpretation remains exploratory.'
HP_VERIFY = "# Verify both stages share the exact canonical pair split.\nHROOT = BUNDLE_DIR / 'input/handiprint'\nHP_SOURCE_INVENTORY = json.loads((HROOT / 'artifact_hashes.json').read_text())\ndef hp_file_sha(path):\n    digest = hashlib.sha256()\n    with Path(path).open('rb') as handle:\n        for block in iter(lambda: handle.read(1024*1024), b''):\n            digest.update(block)\n    return digest.hexdigest()\nfor relative, expected in HP_SOURCE_INVENTORY.items():\n    assert hp_file_sha(HROOT / relative) == expected, relative\nhp_summary = json.loads((HROOT / 'gpu_reproduction_summary.json').read_text())\nhp_environment = json.loads((HROOT / 'results/environment.json').read_text())\nassert hp_summary['status'] == 'completed' and hp_environment['device'] == 'cuda'\nassert hp_summary['executed_code_cells'] == 23\nhp_manifest_path = HROOT / 'results/original_split_manifest.csv'\nassert hp_file_sha(hp_manifest_path) == hp_summary['original_split_sha256']\nassert hp_file_sha(BASE / 'original_split_manifest.csv') == hp_file_sha(hp_manifest_path)\nhp_manifest = pd.read_csv(hp_manifest_path)\nhp_used = hp_manifest[hp_manifest.split.isin(['train','val','test'])].copy()\nassert len(hp_used) == 154 and hp_used.pair_id.nunique() == 77\nassert hp_used.groupby('split').pair_id.nunique().to_dict() == {'test':16,'train':45,'val':16}\nhp_plan = json.loads((HROOT / 'results/plan_lock.json').read_text())\nfor name, expected in hp_plan['model_weight_sha256'].items():\n    assert hp_file_sha(HROOT / 'results/models' / name) == expected, name\nprint('Handiprint GPU artifacts verified; original split shared with blood stage.')\nprint('Recorded GPU:', hp_environment['gpu_name'], '| completed code cells:', hp_summary['executed_code_cells'])\nprint('154 images / 77 pairs; canonical exclusion: pair 81. No raw TIFF reads or CNN fits in default mode.')\n"
HP_TRAIN = "# Optional fresh fits are separate from the frozen results used in this report.\n# HANDIPRINT_TRAINING_SOURCE contains the complete original GPU implementation,\n# including source audit, image processing, HOG baseline, CNN selection and extension.\nassert hashlib.sha256(HANDIPRINT_TRAINING_SOURCE.encode()).hexdigest() == json.loads((BUNDLE_DIR/'INTEGRATION_SOURCES.json').read_text())['handiprint_training_source_sha256']\n\ndef reproduce_handiprint_gpu(raw_root):\n    import os\n    from datetime import datetime, timezone\n    import torch\n    assert torch.cuda.is_available(), 'Handiprint CNN reproduction requires CUDA.'\n    raw_root = Path(raw_root).expanduser().resolve()\n    assert (raw_root/'data/Handiprint_database.xlsx').is_file()\n    assert hp_file_sha(raw_root/'data/split_manifest_final.csv') == hp_summary['original_split_sha256']\n    assert (raw_root/'data/Handiprint_images').is_dir()\n    target = raw_root/'results/handiprint_integrated_reproduction'/datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')\n    target.mkdir(parents=True,exist_ok=False)\n    settings = {'PROJECT_ROOT':str(raw_root),'IMAGE_DIR':str(raw_root/'data/Handiprint_images'),'RESULTS_DIR':str(target/'results'),'NOTEBOOK_SMOKE':'0'}\n    previous = {key:os.environ.get(key) for key in settings}\n    namespace = {'__name__':'__handiprint_gpu_reproduction__'}\n    try:\n        os.environ.update(settings)\n        exec(compile(HANDIPRINT_TRAINING_SOURCE,'<embedded_handiprint_gpu_training>','exec'),namespace)\n        assert namespace['DEVICE'] == 'cuda'\n        assert hp_file_sha(raw_root/'data/split_manifest_final.csv') == hp_summary['original_split_sha256']\n        print('Fresh Handiprint fits saved separately:',target)\n        print('Formal report still uses the verified archived GPU run.')\n    finally:\n        for key,value in previous.items():\n            if value is None:os.environ.pop(key,None)\n            else:os.environ[key]=value\n    return target\n\nRUN_HANDIPRINT_TRAINING = os.environ.get('FOOTWEAR_RUN_HANDIPRINT_TRAINING','0') == '1'\nif RUN_HANDIPRINT_TRAINING:\n    raw_root = os.environ.get('HANDIPRINT_RAW_ROOT')\n    assert raw_root, 'Set HANDIPRINT_RAW_ROOT to the project containing data/ and the exact original TIFFs.'\n    handiprint_reproduction_output = reproduce_handiprint_gpu(raw_root)\nelse:\n    print('Handiprint: reusing recorded GPU fits; no new training or test inference.')\n"
HP_ANALYSIS = "lock=json.loads((HROOT/'results/plan_lock.json').read_text())\nfor name,digest in lock['model_weight_sha256'].items():assert hashlib.sha256((HROOT/'results/models'/name).read_bytes()).hexdigest()==digest,name\npred=pd.read_csv(HROOT/'results/extension/test_predictions.csv')\nhp_metrics=pd.read_csv(HROOT/'results/extension/test_metrics.csv')\nhp_deltas=pd.read_csv(HROOT/'results/extension/paired_model_differences.csv')\nhp_base=pred[(pred.model=='original')&(pred.target_fraction==0)].copy()\nassert len(hp_base)==32 and hp_base.pair_id.nunique()==16\npairs=hp_base.drop_duplicates('pair_id');labels=pairs.y_true.to_numpy();ids=pairs.pair_id.to_numpy();image_ids=hp_base.pair_id.to_numpy();rng=np.random.default_rng(43)\nweights=np.zeros((2000,len(ids)))\nfor b in range(2000):\n for c in np.unique(labels):\n  ix=np.where(labels==c)[0];draw=rng.choice(ix,size=len(ix),replace=True);weights[b]+=np.bincount(draw,minlength=len(ids))\nW=weights[:,[np.where(ids==x)[0][0] for x in image_ids]]\nboot={}\nfor row in hp_metrics.itertuples():\n part=pred[(pred.model==row.model)&(pred.target_fraction==row.target_fraction)]\n scores=part.pivot(index='draw',columns='key',values='score_nike').reindex(columns=hp_base.key).to_numpy()\n y=hp_base.y_true.to_numpy();correct=(scores>0.5)==y[None,:]\n point=np.mean([correct[:,y==c].mean() for c in [0,1]])\n bs=sum((W[:,y==c]@correct[:,y==c].T)/W[:,y==c].sum(axis=1,keepdims=True) for c in [0,1])/2\n bs=bs.mean(axis=1);lo,hi=np.percentile(bs,[2.5,97.5]);assert np.allclose([point,lo,hi],[row.balanced_accuracy,row.ci_low,row.ci_high],rtol=0,atol=1e-12),(row,point,lo,hi)\n boot[(row.model,row.target_fraction)]=bs\nfor row in hp_deltas.itertuples():\n bs=boot['occlusion_augmented',row.target_fraction]-boot['original',row.target_fraction]\n lo,hi=np.percentile(bs,[2.5,97.5]);assert np.allclose([lo,hi],[row.ci_low,row.ci_high],rtol=0,atol=1e-12)\nprint('PASS: model hashes and all 10 extension metric rows and 5 paired bootstrap intervals recomputed from saved predictions.')\n\nprint('Observed severe-mask balanced accuracy:')\ndisplay(hp_metrics)\nprint('Paired model differences (fractions; multiply by 100 for percentage points):')\ndisplay(hp_deltas)\nimport matplotlib.pyplot as plt\nhp_figure_dir = BUNDLE_DIR/'reproduced_analysis/figures'\nhp_figure_dir.mkdir(parents=True,exist_ok=True)\nfig,ax=plt.subplots(figsize=(8,4.2))\nfor name,label,color in [('original','Original CNN','#32658b'),('occlusion_augmented','Occlusion-augmented CNN','#b36825')]:\n    part=hp_metrics[hp_metrics.model.eq(name)].sort_values('target_fraction')\n    ax.plot(100*part.target_fraction,100*part.balanced_accuracy,'o-',label=label,color=color)\n    ax.fill_between(100*part.target_fraction.to_numpy(),100*part.ci_low.to_numpy(),100*part.ci_high.to_numpy(),alpha=.15,color=color)\nax.set(xlabel='Target rectangle area (% of impression crop)',ylabel='Balanced accuracy (%)',ylim=(0,105),title='Handiprint GPU reproduction: exploratory severe occlusion')\nax.legend(loc='lower left');fig.tight_layout()\nfig.savefig(hp_figure_dir/'handiprint_gpu_severe.png',dpi=170)\nplt.show()\n"
REPORT = 'import matplotlib.pyplot as plt\nfrom matplotlib.patches import FancyBboxPatch\nfrom IPython.display import display, Markdown, Image as DisplayImage\nimport io, zipfile, importlib.util, subprocess, sys\n\nlabels={\'majority\':\'Majority\',\'hog\':\'HOG + logistic\',\'legacy_handiprint\':\'Handiprint transfer\',\n    \'rgb\':\'RGB CNN\',\'gray\':\'Grayscale CNN\',\'rgb_occlusion\':\'RGB + occlusion\',\n    \'categorical_size\':\'Categorical size\',\'collection_suffix\':\'Collection suffix\',\n    \'crop_area\':\'Crop area\',\'area_brightness\':\'Area + brightness\'}\norder=[\'majority\',\'legacy_handiprint\',\'hog\',\'rgb\',\'gray\',\'rgb_occlusion\',\n       \'categorical_size\',\'crop_area\',\'area_brightness\',\'collection_suffix\']\nmain=metrics.query("split==\'test\' and cohort==\'all\' and condition==\'All\'").set_index(\'model\').loc[order]\nplt.rcParams.update({\'font.size\':10,\'axes.spines.top\':False,\'axes.spines.right\':False})\nfig,ax=plt.subplots(figsize=(10,5.5));y=np.arange(len(main));values=main.balanced_accuracy.to_numpy()\nax.barh(y,values,color=[\'#64748b\']*3+[\'#2563eb\']*3+[\'#b45309\']*4)\nax.errorbar(values,y,xerr=np.array([values-main.ci_low.to_numpy(),main.ci_high.to_numpy()-values]),fmt=\'none\',ecolor=\'black\',capsize=3)\nax.set_yticks(y,[labels[x] for x in main.index]);ax.invert_yaxis()\nax.set(xlim=(0,1.24),xlabel=\'Balanced accuracy (64 images; 16 pairs)\',title=\'Blood-on-tile: fixed models and diagnostic controls\')\nfor i,v in enumerate(values):ax.text(1.14,i,f\'{v:.1%}\',va=\'center\',fontsize=9)\nfig.text(.5,.01,\'95% pair-bootstrap intervals; a perfect-sample interval is not a population guarantee.\',ha=\'center\',fontsize=8)\nfig.tight_layout(rect=(0,.03,1,1));fig.savefig(WORK/\'figures/test_balanced_accuracy.png\',dpi=170);plt.show()\n\nfig,axes=plt.subplots(1,3,figsize=(11,3.3),sharey=True)\nfor ax,name in zip(axes,[\'rgb\',\'gray\',\'rgb_occlusion\']):\n    for head in selection[\'variants\'][name][\'heads\']:\n        frame=pd.read_csv(GPU/\'models\'/Path(head).with_suffix(\'.csv\'))\n        ax.plot(frame.epoch,frame.val_logloss,label=\'seed \'+head.split(\'seed\')[-1].split(\'.\')[0])\n    ax.set(title=labels[name],xlabel=\'Epoch\',yscale=\'log\');ax.legend(fontsize=8)\naxes[0].set_ylabel(\'Validation log-loss (model selection)\')\nfig.tight_layout();fig.savefig(WORK/\'figures/validation_curves.png\',dpi=170);plt.show()\n\nactivity=test[test.model.isin([\'legacy_handiprint\',\'rgb\'])].groupby(\n    [\'model\',\'pair_id\',\'brand\',\'condition\']).score_nike.mean().unstack(\'condition\').reset_index()\nactivity[\'partial_minus_full\']=activity.Partial-activity.Full\nactivity.to_csv(WORK/\'tables/pair_score_activity.csv\',index=False)\nfig,axes=plt.subplots(1,2,figsize=(8,3.5),sharex=True,sharey=True)\nfor ax,name in zip(axes,[\'legacy_handiprint\',\'rgb\']):\n    for brand,color in [(\'Adidas\',\'#f97316\'),(\'Nike\',\'#2563eb\')]:\n        frame=activity[activity.model.eq(name)&activity.brand.eq(brand)]\n        ax.scatter(frame.Full,frame.Partial,label=brand,color=color,s=36,alpha=.85)\n    ax.plot([0,1],[0,1],\':\',color=\'gray\');ax.axhline(.5,color=\'gray\',lw=.6);ax.axvline(.5,color=\'gray\',lw=.6)\n    ax.set(title=labels[name],xlabel=\'Mean Nike score: full\');ax.legend(fontsize=8)\naxes[0].set_ylabel(\'Mean Nike score: partial\')\nfig.suptitle(\'Model-use activity: paired score changes, sides averaged\')\nfig.tight_layout();fig.savefig(WORK/\'figures/pair_score_activity.png\',dpi=170);plt.show()\n\n# Show observed errors rather than inventing CNN failures.\nerrors=test[test.prediction.ne(test.y)].copy()\nerrors.to_csv(WORK/\'tables/misclassifications.csv\',index=False)\nconfusion=[]\nfor model,group in test.groupby(\'model\'):\n    for actual in [0,1]:\n        for predicted in [0,1]:\n            confusion.append({\'model\':model,\'actual\':actual,\'predicted\':predicted,\n                \'count\':int(((group.y==actual)&(group.prediction==predicted)).sum())})\npd.DataFrame(confusion).to_csv(WORK/\'tables/confusion_counts.csv\',index=False)\nfig,axes=plt.subplots(1,3,figsize=(9,2.8))\nfor ax,model in zip(axes,[\'legacy_handiprint\',\'hog\',\'rgb\']):\n    group=test[test.model.eq(model)]\n    matrix=np.array([[int(((group.y==i)&(group.prediction==j)).sum()) for j in [0,1]] for i in [0,1]])\n    ax.imshow(matrix,cmap=\'Blues\',vmin=0,vmax=32)\n    for i in [0,1]:\n        for j in [0,1]:ax.text(j,i,str(matrix[i,j]),ha=\'center\',va=\'center\',color=\'white\' if matrix[i,j]>16 else \'black\')\n    ax.set_xticks([0,1],[\'Adidas\',\'Nike\']);ax.set_yticks([0,1],[\'Adidas\',\'Nike\']);ax.set(title=labels[model],xlabel=\'Predicted\')\naxes[0].set_ylabel(\'Actual\');fig.tight_layout();fig.savefig(WORK/\'figures/confusion_matrices.png\',dpi=170);plt.show()\n\n# A small case review supports the additional model-use activity.\nexample_rows=errors[errors.model.eq(\'legacy_handiprint\')].sort_values(\'score_nike\').head(4)\nif len(example_rows):\n    fig,axes=plt.subplots(1,len(example_rows),figsize=(10,3))\n    for ax,row in zip(np.atleast_1d(axes),example_rows.itertuples()):\n        original=manifest.set_index(\'key\').loc[row.key]\n        from types import SimpleNamespace\n        path=processed_path(SimpleNamespace(crop_path=original.crop_path,split=\'test\',key=row.key))\n        with Image.open(path) as image:ax.imshow(image)\n        ax.set_title(f\'Pair {row.pair_id}: {row.condition}\\nTrue {row.brand}; Nike score {row.score_nike:.3f}\',fontsize=8);ax.axis(\'off\')\n    fig.suptitle(\'Observed Handiprint-transfer errors; not independent new cases\')\n    fig.tight_layout();fig.savefig(WORK/\'figures/transfer_error_examples.png\',dpi=170);plt.show()\nprint(\'Blood CNN errors observed:\',int(errors.model.isin([\'rgb\',\'gray\',\'rgb_occlusion\']).sum()))\n\n# Architecture diagram: only the binary head is trained.\nfig,ax=plt.subplots(figsize=(10,1.8));ax.set_xlim(0,10);ax.set_ylim(0,2);ax.axis(\'off\')\nfor x,text,color in [(0,\'RGB224 canvas\\naspect preserved\',\'#dbeafe\'),(2.6,\'ImageNet normalization\\nchannel-wise\',\'#e2e8f0\'),(5.2,\'Frozen ResNet18\\n512 features\',\'#dbeafe\'),(7.8,\'Trainable linear head\\n513 parameters + sigmoid\',\'#fed7aa\')]:\n    ax.add_patch(FancyBboxPatch((x,.5),2.1,1,boxstyle=\'round,pad=.08\',facecolor=color,edgecolor=\'#475569\'))\n    ax.text(x+1.05,1,text,ha=\'center\',va=\'center\',fontsize=8)\n    if x<7.8:ax.annotate(\'\',xy=(x+2.5,1),xytext=(x+2.15,1),arrowprops={\'arrowstyle\':\'->\'})\nfig.tight_layout();fig.savefig(WORK/\'figures/architecture.png\',dpi=170);plt.show()\n\npct=lambda x:f\'{100*float(x):.2f}%\'\nci=lambda row:f\'[{pct(row.ci_low)}, {pct(row.ci_high)}]\'\nfullpartial=metrics.query("split==\'test\' and cohort==\'all\'").set_index([\'model\',\'condition\'])\nprobe_rows=[[\'Control\',\'Validation BA\',\'Test BA\',\'Test 95% pair CI\']]\nfor model in [\'categorical_size\',\'crop_area\',\'area_brightness\',\'collection_suffix\']:\n    v=metrics.query("split==\'val\' and cohort==\'all\' and condition==\'All\' and model==@model").iloc[0]\n    t=main.loc[model];probe_rows.append([labels[model],pct(v.balanced_accuracy),pct(t.balanced_accuracy),ci(t)])\nmodel_rows=[[\'Model\',\'Test BA\',\'Adidas recall\',\'Nike recall\']]\nfor model in [\'legacy_handiprint\',\'hog\',\'rgb\',\'gray\',\'rgb_occlusion\']:\n    t=main.loc[model];model_rows.append([labels[model],pct(t.balanced_accuracy),pct(t.recall_adidas),pct(t.recall_nike)])\ncondition_rows=[[\'Model\',\'Full BA\',\'Partial BA\']]\nfor model in [\'legacy_handiprint\',\'hog\',\'rgb\',\'gray\',\'rgb_occlusion\']:\n    condition_rows.append([labels[model],pct(fullpartial.loc[(model,\'Full\'),\'balanced_accuracy\']),pct(fullpartial.loc[(model,\'Partial\'),\'balanced_accuracy\'])])\n\n\n# One report for the two related research stages; no new fitted models.\nhp_result = hp_metrics.set_index([\'model\', \'target_fraction\'])\nhp_table = [[\'Mask area\', \'Original BA\', \'Augmented BA\', \'Gain (pp)\']]\nfor frac in [0., .5, .6, .7, .8]:\n    a = hp_result.loc[(\'original\', frac), \'balanced_accuracy\']\n    b = hp_result.loc[(\'occlusion_augmented\', frac), \'balanced_accuracy\']\n    hp_table.append([f\'{100*frac:.0f}%\', pct(a), pct(b), f\'{100*(b-a)+1e-10:.2f}\'])\nhp_gain = hp_deltas.loc[hp_deltas.target_fraction.eq(.8)].iloc[0]\npages = [\n {\'title\': \'Footwear patterns under occlusion and cross-medium transfer\', \'blocks\': [\n  (\'p\', \'Dora Zhuang | MGSC 673 | Two-stage exploratory research\'),\n  (\'h\', \'Problem and motivation\'),\n  (\'p\', \'Can a classifier distinguish two footwear patterns when impressions are obscured, and what happens when the recording medium changes? Stage 1 investigates simulated occlusion in Handiprints and a training response. Stage 2 studies synthetic-blood impressions from related pairs and tests whether collection conditions offer competing explanations for strong classification. This is two-style classification, not general brand recognition, shoe-source identification or forensic likelihood-ratio estimation.\'),\n  (\'h\', \'Data and independent units\'),\n  (\'table\', [[\'Stage\', \'Train images / pairs\', \'Validation\', \'Test\'], [\'Handiprint\', \'90 / 45\', \'32 / 16\', \'32 / 16\'], [\'Blood on tile\', \'180 / 45\', \'64 / 16\', \'64 / 16\']]),\n  (\'p\', \'ShoeCase metadata describe 78 candidate pairs. Pair 81 remains excluded under the original manifest, leaving 77 pairs and 154 Handiprints; the selected blood subset has 308 eligible images. Both sides, conditions and related media from a pair share one split. These stages are not independent test populations. Seven blood-to-Handiprint links (9, 70, 76, 79, 114, 120, 158) are metadata-inferred; pair 157 retains the declared class and documented filename discrepancy.\'),\n  (\'h\', \'Preparation and provenance\'),\n  (\'p\', \'Handiprint processing converts the original TIFF frame to grayscale, localizes the impression and preserves aspect ratio on a white 224-pixel canvas. Blood red-localization trials were unreliable; the fixed RGB procedure uses reviewed training ROIs and external held-out crops, EXIF handling and aspect-preserving padding. Faint disconnected detail was retained. No perspective correction is claimed. Both workflows can retain substrate cues; the held-out crop interface differs from training.\'),\n  (\'image\', \'train_validation_examples.png\', 6.6, 2.65),\n  (\'p\', \'Blood training and validation examples are shown for documentation after selection, without revising preprocessing. The final package includes all blood canvases; original Handiprint TIFFs remain external, with access and hash-verification instructions.\')\n ]},\n {\'title\': \'Models, training and experiment design\', \'blocks\': [\n  (\'image\', \'architecture.png\', 6.6, 1.18),\n  (\'p\', \'Both stages use ImageNet ResNet18 with frozen backbone and a 512-to-1 linear head (513 trained parameters). Handiprint grayscale is repeated across three channels; blood compares RGB and grayscale from identical crops. ImageNet channel normalization is applied. A smaller backbone supports repeated experiments and continuity; ResNet50 was not benchmarked, so superiority is not claimed.\'),\n  (\'table\', [[\'Choice\', \'Recorded setting\'], [\'Loss / optimizer\', \'Class-weighted BCE for training; Adam, weight decay 0.0001\'], [\'Selection\', \'Unmodified validation log-loss; three seeds: 0, 1, 2\'], [\'Budget\', \'Learning rates 0.001 and 0.01; batch 16; up to 40 epochs; patience 7\'], [\'Augmentation\', \'Small affine, brightness and contrast changes; white masking for augmented variants\'], [\'Occlusion response\', \'Probability 0.5, area range 10–70%; Handiprint masks are crop-relative, blood training masks are canvas-relative\']]),\n  (\'p\', \'Handiprint selects learning rate 0.01 across seeds, then trains three occlusion-augmented heads with the same rate and clean-validation checkpoint rule. Blood selects the RGB rate across seeds and reuses 0.01 for grayscale and occlusion variants. HOG plus balanced logistic regression is a traditional comparison; its regularization is validation-selected. No architecture or hyperparameter is selected using test scores.\'),\n  (\'image\', \'validation_curves.png\', 6.6, 1.98),\n  (\'p\', \'CUDA training is documented for the Handiprint reproduction and all 12 blood fits. A separate Tesla T4 blood reproduction matched the formal losses and model hashes. CNN forward passes in the Handiprint rerun assert CUDA; image processing, augmentation preparation, traditional baselines, statistics and plotting still use CPU. The historical Handiprint transfer comparator is retained from its archive rather than silently replaced by the new GPU heads. Validation reuse makes these curves selection evidence, not unbiased generalization estimates.\')\n ]},\n {\'title\': \'Stage 1: Handiprint occlusion and training response\', \'blocks\': [\n  (\'p\', \'Unmodified test balanced accuracy is 100% for both HOG and the frozen CNN, versus 50% for the majority baseline. Modest masking produced a ceiling, motivating an explicitly post-test exploratory severe-mask extension. The original and augmented CNNs share each simulated test mask; checkpoints use unmodified validation data.\'),\n  (\'image\', \'handiprint_gpu_severe.png\', 6.6, 3.35),\n  (\'table\', hp_table),\n  (\'p\', f\'At 80% crop-area masking, augmentation improves observed balanced accuracy by {100*hp_gain.delta_balanced_accuracy:.2f} percentage points, paired 95% interval [{100*hp_gain.ci_low+1e-10:.2f}, {100*hp_gain.ci_high+1e-10:.2f}]. These GPU reproduction values agree with the rounded earlier report; exact historical parameter equivalence is not claimed. Scores average five fixed mask draws per nonzero severity.\'),\n  (\'p\', \'Mask percentages describe rectangle area relative to the impression crop, not removed tread-pixel percentage. Intervals resample whole pairs within class (2,000 draws), preserving left/right dependence; they condition on the fixed models and masks. The extension differs from the main modest-mask generator and is reported separately. This supports robustness to this simulator, not realistic-scene or population-wide robustness.\')\n ]},\n {\'title\': \'Stage 2: synthetic-blood transfer and classification\', \'blocks\': [\n  (\'p\', \'The historical Handiprint heads are evaluated on the related blood cohort with the documented input adapter. Their 71.88% test balanced accuracy includes 100% Adidas recall and 43.75% Nike recall (18 Nike errors). This combines recording-medium and preprocessing shifts, so it is not an isolated causal estimate of medium change.\'),\n  (\'image\', \'test_balanced_accuracy.png\', 6.6, 3.45),\n  (\'p\', \'Blood HOG achieves 92.19% balanced accuracy (five errors; Adidas recall 90.63%, Nike 93.75%). RGB, grayscale and occlusion-trained CNN ensembles each classify all 64 test images correctly. No observed accuracy advantage distinguishes the three CNN variants. Perfect empirical intervals are not guarantees of perfect population accuracy or evidence of equivalence.\'),\n  (\'image\', \'confusion_matrices.png\', 6.6, 1.98),\n  (\'p\', \'All uncertainty resamples the 16 test pairs, not 64 independent impressions. The RGB-minus-HOG difference is +7.81 percentage points [3.13, 14.06]; RGB-minus-transfer is +28.13 [15.63, 40.63]. These exploratory intervals condition on this split and trained models and do not cover training variability or multiple-comparison selection.\')\n ]},\n {\'title\': \'Using the models and investigating alternative explanations\', \'blocks\': [\n  (\'image\', \'pair_score_activity.png\', 6.6, 2.6),\n  (\'p\', \'The additional model-use activity compares Full/Partial predictions within pairs, averaging sides. For true Nike pairs, the historical transfer score averages 0.486 on full and 0.400 on partial impressions, near or below the fixed 0.5 threshold; blood RGB averages 0.982 and 0.972. These are descriptive, uncalibrated model scores, not evidential probabilities. Transfer Full/Partial BA is 75.00%/68.75%; blood CNNs remain at the ceiling.\'),\n  (\'table\', probe_rows),\n  (\'p\', \'Controls are fitted on training data only. Size is categorical; area uses documented crop geometry; area-plus-brightness combines area with raw-code-value luma mean, luma standard deviation and white fraction. The suffix control reaches 100% on validation and test, and area-plus-brightness reaches 79.69% on test. These show alternative predictive information, not proof that the CNN uses a particular shortcut. The latter probe is a post-primary-test supplement.\'),\n  (\'h\', \'Experiment and decision record\'),\n  (\'table\', [[\'Observation\', \'Decision / learning\'], [\'Handiprint modest masks at ceiling\', \'Extend severity; keep post-test status explicit\'], [\'Severe-mask degradation\', \'Test augmentation under shared masks\'], [\'Blood localization unreliable\', \'Use reviewed RGB crops; log failures\'], [\'Blood CNN variants all correct\', \'Report ceiling; avoid claiming one is better\'], [\'Collection / size / pixel controls predictive\', \'Restrict interpretation; seek independent collection conditions\']])\n ]},\n {\'title\': \'Limitations, ethical use and reproducibility\', \'blocks\': [\n  (\'h\', \'Interpretation limits\'),\n  (\'p\', \'Both stages reuse the original 16 test pairs and include post-test development. They are related observations, not two independent validation studies. Two styles, correlated collection conditions and limited independent shoes prevent broad claims about brand recognition. Handiprint synthetic masks do not reproduce all real occlusions. Seven cross-medium identity links remain inferred; exact-byte checks do not replace physical-identity or near-duplicate review.\'),\n  (\'p\', \'Blood crop workflows differ between training and held-out sets, and remaining substrate, brightness and shape may encode class. Excluding inferred test pairs 70 and 120 leaves 14 pairs: all three blood CNNs remain perfect, HOG is 91.07%, and transfer is 73.21%, using the same predictions without refitting. This sensitivity check does not remove collection confounding. Pair bootstrap omits split, training and collection-session variability.\'),\n  (\'h\', \'Ethical considerations\'),\n  (\'p\', \'Footwear-pattern errors can misdirect investigations. These research classifiers must not be used to identify an individual shoe or person, establish guilt, or supply forensic likelihood ratios. Class scores are not calibrated forensic evidence. Dataset representation is narrow; performance may differ across substrates, shoe wear, recording conditions and brands. Preserve data attribution and modification notices, avoid unsupported certainty, and document model limitations.\'),\n  (\'h\', \'Reproducible workflow\'),\n  (\'p\', \'One notebook contains both stages, training implementations, fixed-model analysis, plots and this report. Default execution verifies recorded artifacts and recomputes Handiprint metrics from saved predictions; blood fixed predictions are reused under their evaluation lock. It does not create new training or claim a new test. Optional training writes separately. All 308 blood inputs, head weights, review histories and GPU reproduction evidence are packaged. The 154 raw Handiprint TIFFs are external because of size; source DOI, exact manifest and original hashes are provided. ImageNet weights may require a first-run download.\'),\n  (\'p\', \'The Handiprint GPU record completed 23 code cells; its global audit flag remains false solely because canonical excluded pair 81 is unresolved. All 154 included source records match the original manifest. The blood reproduction completed 12 fits, matching formal losses and head hashes. The integrated default workflow is checked separately after assembly; the new wrapper does not constitute another real-data training experiment.\'),\n  (\'h\', \'AI assistance and next research step\'),\n  (\'p\', \'Claude and OpenAI Codex assisted with code, provenance checks, experiment implementation, analysis and report drafting. Dora performed crop reviews and ran the recorded GPU experiments. Course permission is governed by instructor policy. The next scientific improvement is independent shoes and collection sessions with style and background conditions disentangled, rather than a larger network chosen after test review.\')\n ]},\n {\'title\': \'References and data access\', \'blocks\': [\n  (\'p\', \'Tibben, A., Carriquiry, A., & McGuire, M. (2023). ShoeCase: A data set of mock crime scene footwear impressions. Iowa State University. https://doi.org/10.25380/iastate.22814438.v1\'),\n  (\'p\', \'Dataset license: CC BY 4.0, as supplied from the dataset record by the author. https://creativecommons.org/licenses/by/4.0/ . Derivative crops retain source attribution, license link and a description of modifications; no endorsement is implied.\'),\n  (\'p\', \'He, K., Zhang, X., Ren, S., & Sun, J. (2016). Deep residual learning for image recognition. CVPR. Torchvision ImageNet ResNet18 weights: resnet18-f37072fd.pth; full SHA256 is verified by the notebook.\'),\n  (\'p\', \'Dalal, N., & Triggs, B. (2005). Histograms of oriented gradients for human detection. CVPR.\'),\n  (\'p\', \'Package access: README.md describes dependencies, default execution, optional separate training, raw Handiprint acquisition and checksum verification. Frozen course and research artifacts are preserved; no full blood archive download is needed. The public GitHub repository is a presentation and does not replace the self-contained processed-data submission.\')\n ]}\n]\n\n# Write a readable Markdown report.\nreport_lines=[]\nfor page in pages:\n    report_lines.append(\'# \'+page[\'title\'])\n    for block in page[\'blocks\']:\n        if block[0]==\'p\':report_lines.append(block[1])\n        elif block[0]==\'h\':report_lines.append(\'## \'+block[1])\n        elif block[0]==\'table\':\n            rows=block[1];report_lines.append(\'| \'+\' | \'.join(rows[0])+\' |\\n| \'+\' | \'.join([\'---\']*len(rows[0]))+\' |\\n\'+\'\\n\'.join(\'| \'+\' | \'.join(row)+\' |\' for row in rows[1:]))\n        elif block[0]==\'image\':report_lines.append(f\'![{block[1]}](../figures/{block[1]})\')\n    report_lines.append(\'\')\n(WORK/\'report/MGSC673_Footwear_Report.md\').write_text(\'\\n\\n\'.join(report_lines))\n\nmissing=[package for module,package in [(\'docx\',\'python-docx\'),(\'reportlab\',\'reportlab\')]\n         if importlib.util.find_spec(module) is None]\nif missing:subprocess.check_call([sys.executable,\'-m\',\'pip\',\'install\',\'-q\',*missing])\nfrom docx import Document\nfrom docx.shared import Inches, Pt\nfrom reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image as PDFImage, PageBreak\nfrom reportlab.lib import colors\nfrom reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle\nfrom reportlab.lib.enums import TA_LEFT\nfrom xml.sax.saxutils import escape\n\ndoc=Document();normal=doc.styles[\'Normal\'];normal.font.name=\'Calibri\';normal.font.size=Pt(10)\nnormal.paragraph_format.space_after=Pt(5)\nfor section in doc.sections:\n    section.top_margin=Inches(.65);section.bottom_margin=Inches(.65)\n# Embed the Matplotlib-bundled font for consistent PDF rendering.\nfrom reportlab.pdfbase import pdfmetrics\nfrom reportlab.pdfbase.ttfonts import TTFont\nimport matplotlib\nfont_folder=Path(matplotlib.get_data_path())/\'fonts/ttf\'\npdfmetrics.registerFont(TTFont(\'MGSCBody\',str(font_folder/\'DejaVuSans.ttf\')))\npdfmetrics.registerFont(TTFont(\'MGSCBold\',str(font_folder/\'DejaVuSans-Bold.ttf\')))\nstyles=getSampleStyleSheet();styles.add(ParagraphStyle(name=\'BodyCompact\',fontName=\'MGSCBody\',fontSize=9.2,leading=12,spaceAfter=6))\nstyles.add(ParagraphStyle(name=\'TableCompact\',fontName=\'MGSCBody\',fontSize=8.7,leading=10.5,spaceAfter=0))\nstyles.add(ParagraphStyle(name=\'PageTitle\',fontName=\'MGSCBold\',fontSize=15,leading=18,spaceAfter=12))\nstyles.add(ParagraphStyle(name=\'SubheadCompact\',fontName=\'MGSCBold\',fontSize=10.5,leading=13,spaceAfter=6,spaceBefore=5))\nstory=[]\nfor i,page in enumerate(pages):\n    # Fixed six body pages and one references page; tested for overflow.\n    if i:\n        doc.add_page_break();story.append(PageBreak())\n    doc.add_heading(page[\'title\'],0 if i==0 else 1)\n    story.append(Paragraph(escape(page[\'title\']),styles[\'PageTitle\']))\n    for block in page[\'blocks\']:\n        kind=block[0]\n        if kind==\'p\':\n            doc.add_paragraph(block[1]);story.append(Paragraph(escape(block[1]),styles[\'BodyCompact\']))\n        elif kind==\'h\':\n            doc.add_heading(block[1],2);story.append(Paragraph(escape(block[1]),styles[\'SubheadCompact\']))\n        elif kind==\'image\':\n            path=WORK/\'figures\'/block[1]\n            with Image.open(path) as image: aspect=image.width/image.height\n            image_width=min(block[2]*72,block[3]*72*aspect)\n            image_height=image_width/aspect\n            doc.add_picture(str(path),width=Inches(image_width/72))\n            story.append(PDFImage(str(path),width=image_width,height=image_height));story.append(Spacer(1,7))\n        elif kind==\'table\':\n            values=block[1];table=doc.add_table(rows=1,cols=len(values[0]));table.style=\'Light Shading Accent 1\'\n            for cell,value in zip(table.rows[0].cells,values[0]):cell.text=value\n            for row in values[1:]:\n                for cell,value in zip(table.add_row().cells,row):cell.text=value\n            for row in table.rows:\n                for cell in row.cells:\n                    for paragraph in cell.paragraphs:\n                        for run in paragraph.runs:run.font.size=Pt(9)\n            available=6.95*72;columns=len(values[0]);widths=[available/columns]*columns\n            if columns==2:widths=[available*.29,available*.71]\n            pdf_rows=[[Paragraph(escape(value),styles[\'TableCompact\']) for value in row] for row in values]\n            table_pdf=Table(pdf_rows,colWidths=widths,hAlign=\'LEFT\',repeatRows=1)\n            table_pdf.setStyle(TableStyle([(\'BACKGROUND\',(0,0),(-1,0),colors.HexColor(\'#dbeafe\')),(\'VALIGN\',(0,0),(-1,-1),\'TOP\'),(\'GRID\',(0,0),(-1,-1),.3,colors.HexColor(\'#94a3b8\')),(\'LEFTPADDING\',(0,0),(-1,-1),5),(\'RIGHTPADDING\',(0,0),(-1,-1),5),(\'TOPPADDING\',(0,0),(-1,-1),4),(\'BOTTOMPADDING\',(0,0),(-1,-1),2)]))\n            story.append(table_pdf);story.append(Spacer(1,8))\ndoc.save(WORK/\'report/MGSC673_Footwear_Report.docx\')\ndef report_footer(canvas,document):\n    canvas.setFont(\'MGSCBody\',8)\n    canvas.drawString(55,23,\'MGSC 673 | Dora Zhuang\')\n    canvas.drawRightString(557,23,str(canvas.getPageNumber()))\nSimpleDocTemplate(str(WORK/\'report/MGSC673_Footwear_Report.pdf\'),title=\'Footwear patterns under occlusion and cross-medium transfer\',author=\'Dora Zhuang\',pagesize=(612,792),leftMargin=55,rightMargin=55,topMargin=42,bottomMargin=42).build(story,onFirstPage=report_footer,onLaterPages=report_footer)\nprint(\'Report saved in Word, PDF and Markdown:\',WORK/\'report\')\nprint(\'The report, figures and visible notebook results are saved alongside their source tables.\')\n'
PACKAGER = '"""Package the saved, executed integrated notebook with fixed research artifacts."""\nfrom pathlib import Path\nimport argparse\nimport hashlib\nimport json\nimport zipfile\nimport pandas as pd\n\n\ndef sha(path):\n    digest=hashlib.sha256()\n    with Path(path).open(\'rb\') as handle:\n        for block in iter(lambda:handle.read(1024*1024),b\'\'):digest.update(block)\n    return digest.hexdigest()\n\n\ndef build(project,output=None):\n    project=Path(project).resolve()\n    notebook=json.loads((project/\'MGSC673_Project.ipynb\').read_text())\n    cells=[c for c in notebook[\'cells\'] if c[\'cell_type\']==\'code\']\n    assert cells and all(c.get(\'execution_count\') is not None for c in cells),\'Execute all cells and save first.\'\n    assert not any(o.get(\'output_type\')==\'error\' for c in cells for o in c.get(\'outputs\',[]))\n    manifest=pd.read_csv(project/\'input/gpu/dataset_manifest.csv\')\n    assert len(manifest)==308 and manifest.key.is_unique\n    for row in manifest.itertuples():\n        assert sha(project/\'input/inputs\'/row.split/f\'{row.key}.png\')==row.crop_sha256,row.key\n    hand=project/\'input/handiprint\'\n    for relative,digest in json.loads((hand/\'artifact_hashes.json\').read_text()).items():\n        assert sha(hand/relative)==digest,relative\n    assert sha(hand/\'results/original_split_manifest.csv\')==sha(project/\'input/locked/original_split_manifest.csv\')\n    assert (project/\'reproduced_analysis/report/MGSC673_Footwear_Report.pdf\').is_file()\n    names=[\'MGSC673_Project.ipynb\',\'README.md\',\'requirements.txt\',\'DATA_PROVENANCE.md\',\'portable_manifest.csv\',\'build_submission.py\',\'INTEGRATION_SOURCES.json\']\n    if (project/\'INTEGRATION_EXECUTION.json\').is_file():names.append(\'INTEGRATION_EXECUTION.json\')\n    selected=[project/name for name in names]\n    for root in [\'input\',\'legacy\',\'histories\',\'reproduced_analysis\',\'reproduction_check\']:\n        selected.extend(p for p in (project/root).rglob(\'*\') if p.is_file() and not any(x.startswith(\'.\') or x==\'__pycache__\' for x in p.relative_to(project).parts))\n    assert all(p.is_file() for p in selected)\n    assert len([p for p in selected if p.suffix==\'.ipynb\'])==1,\'Submit one integrated notebook.\'\n    output=Path(output) if output else project.parent/\'MGSC673_Integrated_Submission.zip\'\n    assert not output.exists(),\'Preserve existing ZIP; choose a new output path.\'\n    temporary=output.with_suffix(\'.partial.zip\')\n    inventory={str(p.relative_to(project)):sha(p) for p in sorted(selected)}\n    with zipfile.ZipFile(temporary,\'w\',zipfile.ZIP_DEFLATED) as archive:\n        for p in sorted(selected):archive.write(p,project.name+\'/\'+str(p.relative_to(project)))\n        archive.writestr(project.name+\'/PACKAGE_SHA256.json\',json.dumps(inventory,indent=2))\n    with zipfile.ZipFile(temporary) as archive:\n        assert archive.testzip() is None\n        for relative,digest in inventory.items():assert hashlib.sha256(archive.read(project.name+\'/\'+relative)).hexdigest()==digest\n    temporary.replace(output)\n    print(\'Integrated submission archive:\',output,flush=True)\n    print(f\'Size: {output.stat().st_size/1024**2:.1f} MiB\',flush=True)\n    return output\n\n\nif __name__==\'__main__\':\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--project\',type=Path,default=Path(__file__).parent)\n    parser.add_argument(\'--output\',type=Path)\n    args=parser.parse_args();build(args.project,args.output)\n'
README = "# Integrated footwear occlusion and cross-medium project\n\nThis package contains one notebook and one report covering two related stages: Handiprint occlusion/GPU reproduction and synthetic-blood cross-medium analysis. It preserves both original result archives as separate source artifacts outside this package; it never replaces historical CPU results or the previously frozen course submission.\n\n## Default execution\n\n1. Extract this entire ZIP. Install `requirements.txt` in a compatible environment, preserving a matched torch/torchvision pair. The recorded GPU runs used torch 2.11.0+cu130 and torchvision 0.26.0+cu130; the default workflow can also run on CPU, with its runtime recorded separately. Default CPU inference is not relabelled as GPU training.\n2. Open `MGSC673_Project.ipynb` from the extracted project directory, or set `FOOTWEAR_ANALYSIS_BUNDLE` to that directory before starting the kernel.\n3. Leave `FOOTWEAR_RUN_TRAINING` and `FOOTWEAR_RUN_HANDIPRINT_TRAINING` unset (or 0), restart and run all, then save outputs. Default execution checks recorded artifacts, recomputes Handiprint metrics and paired bootstrap intervals from saved predictions, and reuses fixed blood predictions under the existing evaluation lock. No CNN is fitted and no new independent experiment is claimed.\n4. The first run may download the approximately 45 MB public ImageNet ResNet18 backbone. Its SHA256 must match the formal record. The notebook's dedicated check explains offline placement in `input/backbone/` or the torch cache.\n5. Figures, tables and the integrated PDF/Word/Markdown report are written to `reproduced_analysis/`. The report body targets six pages plus references. Run `python build_submission.py` only after saving the completed notebook; it refuses to overwrite an existing final ZIP.\n\nThe package includes all 308 prepared blood RGB224 images, exact frozen manifests, head weights, source predictions, review handoffs, both GPU reproduction records and complete training implementations in the single notebook. Public repository code alone is not a substitute for these artifacts.\n\n## Optional Handiprint training: external raw TIFFs\n\nThe 154 eligible original TIFFs total about 3.49 GiB and are not bundled. Source dataset: Tibben, Carriquiry & McGuire (2023), *ShoeCase: A data set of mock crime scene footwear impressions*, https://doi.org/10.25380/iastate.22814438.v1 (CC BY 4.0 as provided from the dataset record by the author). Obtain the Handiprint archive and `Handiprint_database.xlsx` from the dataset. The original archive has 156 TIFF members; use the preserved manifest to select the 154 included images, retaining the canonical pair-81 exclusion. No full blood archive is needed.\n\nSet up an external raw-data project:\n\n```\nRAW_PROJECT/\n  data/\n    Handiprint_database.xlsx\n    split_manifest_final.csv\n    Handiprint_images/  # relative paths equal matched_path in the canonical manifest\n```\n\nCopy `input/handiprint/results/original_split_manifest.csv` byte-for-byte to `RAW_PROJECT/data/split_manifest_final.csv`. Its SHA256 is `20f942824a8c45c102837998cf2eb0b9f6d8cc9b243fa1ae87bef3db4f03d11d`. For each manifest row with split train, val or test, match the TIFF by its unique basename, write it under `Handiprint_images/<matched_path>`, and require its bytes to match the row's `sha256`. Preserve the downloaded archive. The notebook repeats the audit and refuses a changed included cohort or changed file hashes. A raw-data acquisition link and exact identity checks are provided instead of distributing the multi-gigabyte raw set.\n\nIn a CUDA kernel, set `HANDIPRINT_RAW_ROOT` to RAW_PROJECT and `FOOTWEAR_RUN_HANDIPRINT_TRAINING=1`. The complete source implementation is embedded in `HANDIPRINT_TRAINING_SOURCE`; the wrapper executes it in a separate namespace so it does not overwrite blood-stage variables. All Handiprint CNN forward passes assert CUDA. Outputs go to a unique `RAW_PROJECT/results/handiprint_integrated_reproduction/<UTC>/` folder, never the archived formal artifacts. Default report results remain the verified recorded GPU run, not a newly selected favorable fit. The newly assembled wrapper is distinct from the already completed real-data GPU run and must not be represented as an additional completed training experiment.\n\nOptional blood fits are controlled separately by `FOOTWEAR_RUN_TRAINING=1`, use the bundled prepared inputs, and write to `results/blood_reproduction_v1`. For fresh fits, work on a copy of the package. CPU preprocessing, augmentation preparation, HOG/logistic regression, statistics and plotting are retained. The GPU condition refers to CNN computation, not an entirely CPU-free program.\n\n## Provenance and interpretation\n\n`INTEGRATION_SOURCES.json` records the exact source-archive checksums and embedded training-source checksum. Immutable Handiprint artifacts are covered by `input/handiprint/artifact_hashes.json`; the final package has a full `PACKAGE_SHA256.json`. Historical Handiprint heads remain the blood-transfer comparator; the new GPU heads are not silently substituted. The stages share original pairs and prior test exposure, so this is exploratory, not two independent confirmatory studies. Mask area is not the fraction of tread removed. Collection, size and crop cues limit interpretation of blood-stage perfect scores.\n\nThe original Handiprint summary has `audit_passed: false` because pair 81 remains unresolved and excluded. All 154 included image identities match the canonical manifest. The rerun extracted only the eligible files, so both excluded sides are absent locally; this does not change the original missing-side history.\n\nAI assistance is disclosed factually in the report. Instructor approval of topic, permitted AI use and any specific GPU policy are determined by course records. The individual author must understand and be able to explain the implementation and conclusions.\n"

def sha(path):
    digest=hashlib.sha256()
    with Path(path).open('rb') as handle:
        for block in iter(lambda:handle.read(1024*1024),b''):digest.update(block)
    return digest.hexdigest()

def extract_verified(archive_path,destination,expected_sha):
    archive_path=Path(archive_path)
    assert sha(archive_path)==expected_sha, f'Unexpected source archive: {archive_path.name}. Preserve it and request review.'
    with zipfile.ZipFile(archive_path) as archive:
        assert archive.testzip() is None
        for item in archive.infolist():
            path=(destination/item.filename).resolve()
            assert path.is_relative_to(destination.resolve()),item.filename
            assert ((item.external_attr>>16)&0o170000)!=0o120000,'Symlinks are not accepted.'
        archive.extractall(destination)
    inventories=list(destination.rglob('PACKAGE_SHA256.json'))
    assert len(inventories)==1
    inventory_path=inventories[0];root=inventory_path.parent
    inventory=json.loads(inventory_path.read_text())
    actual={str(p.relative_to(root)) for p in root.rglob('*') if p.is_file() and p!=inventory_path}
    assert actual==set(inventory),'Source inventory coverage differs.'
    for relative,expected in inventory.items():
        path=(root/relative).resolve();assert path.is_relative_to(root.resolve())
        assert sha(path)==expected,relative
    return root,inventory

def markdown(source):return {'cell_type':'markdown','metadata':{},'source':source.splitlines(keepends=True)}
def code(source):
    ast.parse(source)
    return {'cell_type':'code','metadata':{},'source':source.splitlines(keepends=True),'outputs':[],'execution_count':None}

def build(blood_zip,handiprint_zip,output):
    output=Path(output).resolve();output.mkdir(parents=True,exist_ok=True)
    project=output/'MGSC673_Integrated_Project'
    assert not project.exists(),'Use a new output directory; existing projects are never overwritten.'
    with tempfile.TemporaryDirectory(prefix='verified_sources_',dir=output) as temporary:
        temp=Path(temporary)
        blood,blood_inventory=extract_verified(blood_zip,temp/'blood',BLOOD_SHA)
        hand,hand_inventory=extract_verified(handiprint_zip,temp/'hand',HAND_SHA)
        original=json.loads((blood/'MGSC673_Project.ipynb').read_text())
        gpu_notebook=json.loads((hand/'Handiprint_GPU_Reproduction.ipynb').read_text())
        assert len(original['cells'])==25 and len(gpu_notebook['cells'])==44
        hp_source='\n\n'.join(''.join(c['source']) for c in gpu_notebook['cells'] if c['cell_type']=='code')
        ast.parse(hp_source)
        assert "'''" not in hp_source, 'Unexpected raw-string delimiter in source.'
        shutil.copytree(blood,project,ignore=shutil.ignore_patterns('MGSC673_Project.ipynb','PACKAGE_SHA256.json','build_submission.py','README.md'))
        hroot=project/'input/handiprint';hroot.mkdir()
        shutil.copytree(hand/'results',hroot/'results')
        for name in ['gpu_execution_log.txt','gpu_reproduction_summary.json']:
            shutil.copy2(hand/name,hroot/name)
        hp_inventory={str(p.relative_to(hroot)):sha(p) for p in sorted(hroot.rglob('*')) if p.is_file()}
        (hroot/'artifact_hashes.json').write_text(json.dumps(hp_inventory,indent=2))
        assert sha(hroot/'results/original_split_manifest.csv')==sha(project/'input/locked/original_split_manifest.csv')
        (project/'INTEGRATION_SOURCES.json').write_text(json.dumps({
            'blood_archive_sha256':BLOOD_SHA,'handiprint_archive_sha256':HAND_SHA,
            'blood_source_inventory_entries':len(blood_inventory),'handiprint_source_inventory_entries':len(hand_inventory),
            'handiprint_training_source_sha256':hashlib.sha256(hp_source.encode()).hexdigest(),
            'scientific_policy':'Preserve fitted models, masks, original split and formal predictions. Default integration is not a new training or test experiment.'
        },indent=2))
        setup=''.join(original['cells'][2]['source'])
        start=setup.index('ROOT = Path(');end=setup.index('BASE = ',start)
        setup=setup[:start]+"assert BUNDLE_DIR is not None, 'Set FOOTWEAR_ANALYSIS_BUNDLE to the extracted integrated project.'\nROOT = BUNDLE_DIR\n"+setup[end:]
        setup=setup.replace("Path.cwd()/'MGSC673_Portable_Project'","Path.cwd()/'MGSC673_Integrated_Project'")
        cells=[markdown(INTRO),markdown(RUN_MODES),code(setup),markdown(HP_INTRO),code(HP_VERIFY),
               markdown(HP_TRAINING_INTRO),code("HANDIPRINT_TRAINING_SOURCE = r'''"+hp_source+"'''\n"),code(HP_TRAIN),
               markdown(HP_ANALYSIS_INTRO),code(HP_ANALYSIS),markdown(BLOOD_INTRO)]
        for index in range(3,25):
            cell=copy.deepcopy(original['cells'][index])
            if index==12:cell=markdown('### Historical Handiprint transfer-comparator provenance\nThe blood transfer comparator remains the original archived heads. It is not replaced by the GPU reproduction above. These archived values describe development history; newly verified Handiprint GPU results are presented in Stage 1.')
            elif index==21:cell=markdown('## Integrated interpretation and report\nBlood figures, Handiprint GPU results, experiment decisions and common limitations are synthesized into one report. Existing weights and predictions are preserved; no favorable run is selected after integration.')
            elif index==22:cell=code(REPORT)
            elif index==23:cell=markdown('## Completed outputs\nThe single notebook contains both stages and their training implementations. Default execution checks frozen artifacts and reuses recorded predictions; optional training is separate. The report covers both stages. Save the executed notebook before running the independent packager.')
            headings={4:'### Blood data, identity linkage and leakage checks',6:'### Blood preprocessing and training-only examples',10:'#### Blood review-history reconciliation',14:'### Blood model definitions, training and GPU provenance',17:'### Blood fixed-model reproduction and diagnostic controls',19:'### Blood shoe-pair uncertainty and sensitivity',21:'## 4. Integrated interpretation and report',23:'## 5. Saved outputs and packaging'}
            if index in headings:
                text=''.join(cell['source'])
                text=headings[index]+'\n'+text.split('\n',1)[1]
                cell['source']=text.splitlines(keepends=True)
            if cell['cell_type']=='code':
                cell['outputs']=[];cell['execution_count']=None;ast.parse(''.join(cell['source']))
            cells.append(cell)
        notebook={'cells':cells,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python'}},'nbformat':4,'nbformat_minor':5}
        for i,cell in enumerate(cells):cell['id']=f'integrated-{i:03d}'
        (project/'MGSC673_Project.ipynb').write_text(json.dumps(notebook,indent=1)+'\n')
        (project/'README.md').write_text(README)
        (project/'build_submission.py').write_text(PACKAGER)
        req=(project/'requirements.txt').read_text()
        req+='\n# Integrated notebook execution and original Handiprint metadata.\nopenpyxl>=3.1\nscipy>=1.11\nnbformat>=5.9\nnbclient>=0.9\n'
        (project/'requirements.txt').write_text(req)
        data=(project/'DATA_PROVENANCE.md').read_text()
        data+='\n\n## Integrated Handiprint GPU stage\nThe package includes recorded GPU model heads, predictions, masks and summaries, plus the unchanged canonical manifest for 154 eligible Handiprints. Original TIFFs are not bundled because of size; use the dataset DOI and README acquisition instructions. Historical source versions and CPU results are not relabelled as GPU runs. All original Handiprint image-processing and training code is embedded in the single notebook; source hashes are recorded in INTEGRATION_SOURCES.json.\n'
        (project/'DATA_PROVENANCE.md').write_text(data)
    print('Integrated candidate assembled:',project,flush=True)
    return project

def execute(project):
    import nbformat
    from nbclient import NotebookClient
    from jupyter_client import KernelManager
    from jupyter_client.kernelspec import KernelSpecManager
    project=Path(project).resolve()
    notebook_path=project/'MGSC673_Project.ipynb'
    notebook=nbformat.read(notebook_path,as_version=4)
    runtime=project.parent/'.integration_runtime/kernels/integrated'
    runtime.mkdir(parents=True,exist_ok=True)
    (runtime/'kernel.json').write_text(json.dumps({'argv':[sys.executable,'-m','ipykernel_launcher','-f','{connection_file}'],'display_name':'Integrated reproduction','language':'python','env':{'FOOTWEAR_ANALYSIS_BUNDLE':str(project),'FOOTWEAR_RUN_TRAINING':'0','FOOTWEAR_RUN_HANDIPRINT_TRAINING':'0'}}))
    manager=KernelManager(kernel_name='integrated',kernel_spec_manager=KernelSpecManager(kernel_dirs=[str(runtime.parent)]))
    def start(cell,cell_index,**kwargs):
        if cell.cell_type=='code':print(f'Executing cell {cell_index+1}/{len(notebook.cells)}',flush=True)
    client=NotebookClient(notebook,timeout=1800,km=manager,resources={'metadata':{'path':str(project)}},on_cell_start=start)
    try:
        client.execute()
        nbformat.write(notebook,notebook_path)
    except BaseException:
        nbformat.write(notebook,project/'integration_execution_debug.ipynb')
        print('Stopped; diagnostic notebook preserved. Do not delete evaluation locks.',flush=True)
        raise
    finally:
        if manager.has_kernel:manager.shutdown_kernel(now=True)
    cells=[c for c in notebook.cells if c.cell_type=='code']
    assert all(c.execution_count is not None for c in cells)
    assert not any(o.get('output_type')=='error' for c in cells for o in c.get('outputs',[]))
    outputs='\n'.join(str(o.get('text','')) for c in cells for o in c.get('outputs',[]) if o.get('output_type')=='stream')
    assert 'Handiprint: reusing recorded GPU fits; no new training or test inference.' in outputs
    assert 'Reusing archived GPU models; no CNN retraining.' in outputs
    (project/'INTEGRATION_EXECUTION.json').write_text(json.dumps({'status':'completed','executed_code_cells':len(cells),'default_modes_verified':True,'new_cnn_training':False,'note':'Default integration execution, not a new independent test.'},indent=2))
    print('Integrated notebook executed and saved.',flush=True)

def package(project):
    namespace={'__name__':'integrated_packager'}
    exec(compile((project/'build_submission.py').read_text(),str(project/'build_submission.py'),'exec'),namespace)
    return namespace['build'](project)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--blood-zip',required=True,type=Path)
    parser.add_argument('--handiprint-zip',required=True,type=Path)
    parser.add_argument('--output-dir',required=True,type=Path)
    parser.add_argument('--execute',action='store_true')
    args=parser.parse_args()
    project=build(args.blood_zip,args.handiprint_zip,args.output_dir)
    if args.execute:
        execute(project)
        package(project)
    else:print('No execution or training requested. Candidate is not yet a final submission.',flush=True)

if __name__=='__main__':main()
